  /* ------------------------------------------------------------------
     Темпы зоны «Тихого хода» (исследование 03; Beatport-BPM приблизительны).
     ------------------------------------------------------------------ */
  tempos: [
    { style: 'Эмбиент и дрон', bpm: 'свободный или 70–100', feel: 'Бочки нет или она совсем мягкая, как в «Sundays are for…» Joan Gila; темп здесь скорее ориентир для эха и LFO. Во вкладке «ритмы» это бит «Эмбиент без бочки».' },
    { style: 'Даунтемпо и чиллаут', bpm: '80–95', feel: 'Ленивый грув со свингом 50–60 %, бочка не на каждой доле. Есть вариант в половинном темпе: в проекте 120–130, но бочка и хлопок играют вдвое реже, и трек ощущается как 60–65.' },
    { style: 'ISHOME, эпоха carpet watcher', bpm: '90–110', feel: 'Вязкий бит и призрачные мелодии; заглавный трек около 96, «Ken Tavr» около 91.' },
    { style: 'Cosmic и медленный транс', bpm: '90–113', feel: 'Итальянский cosmic жил около 90–110, «slow trance» в тегах слушателей около 95–113. Ровная бочка без свинга, пульсирующие арпеджио и длинные пэды.' },
    { style: 'Медленное даб-техно', bpm: 'до 112', feel: 'Andy Stott медленнее 100, Lowtec «Workshop 06» на 112: мутная бочка, низкий гул и аккорды в эхе. Клубные рецепты даб-техно бывают и на 145, в курсе мы их замедляем.' },
    { style: 'Geju и chillrave', bpm: '95–118', feel: 'У Geju чаще всего 98–114, в среднем около 106; у артистов chillrave из сета reeto в основном 95–118. Неторопливый вязкий грув («чаггинг»), ручные барабаны, живые звуки.' },
    { style: 'Slow house', bpm: '110–115', feel: 'Свинг 60–65 %, бубен и щелчки пальцами чуть мимо сетки.' },
    { style: 'Organic house', bpm: '122–125', feel: 'Клубный темп, выше нашей основной зоны 90–118; сюда доходят только отдельные треки. Свинг 60–65 %, шейкер ровными шестнадцатыми с тяжёлым свингом.' },
    { style: 'IDM и брейки (Gnatenko)', bpm: '93–136', feel: 'Широкий разброс: сложные ломаные ритмы и брейкбиты (нарезанные живые барабаны), которые растворяются в эмбиенте.' }
  ],

